select
  *
from SYS_BATCH_UNISTART_DETAIL t
where  SEQ_NO = #{seqNo, jdbcType=VARCHAR}

    and STATUS = #{status, jdbcType=VARCHAR}


    and DETAIL_SEQ_NO = #{detalSeqNo, jdbcType=VARCHAR}


    and ORDER_NO < #{orderNo, jdbcType=VARCHAR}

select
  *
from SYS_BATCH_UNISTART_DETAIL t
where (STATUS = 'UNR' OR STATUS = 'RUN')
AND SEQ_NO = #{seqNo, jdbcType=VARCHAR}
AND ORDER_NO   <  #{orderNo, jdbcType=NUMERIC}

mapper.update:
update
    SYS_BATCH_UNISTART_DETAIL
set STATUS      = #{status, jdbcType=TIMESTAMP},
    END_TIME    = #{endTime, jdbcType=TIMESTAMP},
    UPDATE_TIME = #{endTime, jdbcType=TIMESTAMP}
WHERE SEQ_NO = #{seqNo, jdbcType=VARCHAR}
  AND DETAIL_SEQ_NO = #{detailSeqNo, jdbcType=VARCHAR}
  AND ORDER_NO >=  #{orderNo, jdbcType=NUMERIC}

update
    SYS_BATCH_UNISTART
set STATUS      = #{status, jdbcType=TIMESTAMP},
    END_TIME    = #{endTime, jdbcType=TIMESTAMP},
    UPDATE_TIME = #{endTime, jdbcType=TIMESTAMP}
WHERE SEQ_NO = #{seqNo, jdbcType=VARCHAR}

